mapper.select:
SELECT  FROM channel_reply_deliveries d
WHERE  AND d.reply_message_id = #{receipt}
LIMIT 1

WITH changed AS (
       UPDATE channel_reply_deliveries d SET lease_until = now() + interval '30 seconds', updated_at = now()
       WHERE  AND d.input_event_id = #{inputID}
         AND d.lease_owner = #{owner} AND d.state IN ('sent', 'completed') AND d.lease_until > now()
       RETURNING input_event_id
   ) SELECT input_event_id FROM changed

WITH changed AS (
       UPDATE channel_reply_deliveries d SET lease_until = now() - interval '1 millisecond', updated_at = now()
       WHERE  AND d.input_event_id = #{inputID}
         AND d.lease_owner = #{owner} AND d.state = 'sent'
       RETURNING input_event_id
   ) SELECT input_event_id FROM changed

WITH changed AS (
       UPDATE channel_reply_deliveries d SET state = 'completed', updated_at = now()
       WHERE  AND d.input_event_id = #{inputID}
         AND d.lease_owner = #{owner} AND d.state IN ('sent', 'completed') AND d.lease_until > now()
       RETURNING input_event_id
   ) SELECT input_event_id FROM changed

SELECT d.lease_until FROM channel_reply_deliveries d
WHERE  AND d.state = 'sent' AND d.lease_owner <> #{owner}
ORDER BY d.lease_until LIMIT 1
